module profit_calculator (\n    input clk,\n    input rst_n,\n    input start,\n    input [31:0] profit_cents,\n    input [15:0] pita_profit_cents,\n    input [15:0] pizza_profit_cents,\n    output reg [15:0] pitas,\n    output reg [15:0] pizzas,\n    output reg valid,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE     = 3'd0;\n    localparam [2:0] COMPUTE  = 3'd1;\n    localparam [2:0] CHECK    = 3'd2;\n    localparam [2:0] OUTPUT   = 3'd3;\n    localparam [2:0] INCREMENT = 3'd4;\n    localparam [2:0] FINISHED = 3'd5;\n\n    reg [2:0] state;\n    reg [15:0] x;\n    reg [15:0] y;\n    reg [15:0] max_iter;\n    reg [4:0] sol_count;\n    reg [31:0] remainder;\n    reg [31:0] prod_calc;\n    reg [31:0] y_calc;\n    reg [31:0] check;\n    reg solution_valid;\n\n    localparam [15:0] MAX_ITERATIONS = 16'd1000;\n    localparam [4:0] MAX_SOLUTIONS = 5'd16;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            pitas <= 16'd0;\n            pizzas <= 16'd0;\n            valid <= 1'b0;\n            done <= 1'b0;\n            x <= 16'd0;\n            y <= 16'd0;\n            max_iter <= 16'd0;\n            sol_count <= 5'd0;\n            remainder <= 32'd0;\n            prod_calc <= 32'd0;\n            y_calc <= 32'd0;\n            check <= 32'd0;\n            solution_valid <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    valid <= 1'b0;\n                    done <= 1'b0;\n                    sol_count <= 5'd0;\n                    max_iter <= 16'd0;\n                    if (start) begin\n                        x <= 16'd0;\n                        y <= 16'd0;\n                        state <= COMPUTE;\n                    end\n                end\n\n                COMPUTE: begin\n                    prod_calc <= x * pita_profit_cents;\n                    remainder <= profit_cents - (x * pita_profit_cents);\n                    state <= CHECK;\n                end\n\n                CHECK: begin\n                    solution_valid <= (remainder >= 32'd0) && \n                                   (remainder[15:0] != 16'd0) && \n                                   ((remainder % pizza_profit_cents) == 32'd0) && \n                                   ((remainder / pizza_profit_cents) <= 16'd65535);\n                    y_calc <= (remainder / pizza_profit_cents);\n                    check <= y_calc * pizza_profit_cents;\n\n                    if (x > MAX_ITERATIONS || sol_count >= MAX_SOLUTIONS) begin\n                        state <= FINISHED;\n                    end else if (solution_valid) begin\n                        state <= OUTPUT;\n                    end else begin\n                        state <= INCREMENT;\n                    end\n                end\n\n                OUTPUT: begin\n                    pitas <= x;\n                    pizzas <= y_calc[15:0];\n                    valid <= 1'b1;\n                    sol_count <= sol_count + 5'd1;\n                    state <= INCREMENT;\n                end\n\n                INCREMENT: begin\n                    valid <= 1'b0;\n                    x <= x + 16'd1;\n                    max_iter <= max_iter + 16'd1;\n                    if (max_iter >= MAX_ITERATIONS) begin\n                        state <= FINISHED;\n                    end else begin\n                        state <= COMPUTE;\n                    end\n                end\n\n                FINISHED: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule